custom_css:
/* 燕归来@夜行性鲨鱼
   禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎  */
/* 气泡核心结构-一体化单体版 - 深色主题重构（仅颜色改动） */

body.bubblechat .mes,
body.bubblechat .mes[is_user="true"],
.mes {
    padding: 15px !important;
    padding-top: 240px !important;
    padding-bottom: 30px !important;
    border-radius: 0 !important;
    border: 1px solid #3a3a3a !important; /* 原 #D0D0D0 → 深灰 */
    box-shadow: 4px 4px 15px rgba(0, 0, 0, 0.25) !important; /* 阴影加深 */
    max-width: 360px !important;
    margin: 30px auto 15px auto !important;
    position: relative;
    background-color: #1e1e1e !important; /* 原 #fff → 深色基底 */
    background-image: none !important;
    box-sizing: border-box !important;
    overflow: visible !important;
}

.mes_block {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}

.mes_text {
    padding: 0 !important;
    margin: 0 !important;
    text-align: justify !important;
    text-justify: inter-ideograph !important;
    color: #e0e0e0 !important; /* 新增正文主色，保证深底浅字 */
}

/* UI全局排版优化:去框减负、呼吸感布局 */
* {
    border-radius: 0 !important;
}

/* 1. 设置容器与标题完全扁平化(针对图1要求) */
.drawer-content .range-block,
.inline-drawer-header h4,
.standoutHeader,
h4,
h4[data-i18n] {
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
    color: #bbbbbb !important; /* 原 #555 → 浅灰 */
    text-shadow: none !important;
    border-radius: 0 !important;
    margin-bottom: 5px !important;
    border-bottom: 1px dashed #4a4a4a !important; /* 原 #E0E0E0 → 深灰 */
    padding-bottom: 5px !important;
}

/* ++【新增】彻底修复图1扩展列表的深色块突兀问题 ++ */
.inline-drawer-toggle,
.list-group-item,
.drawer-content .list-group-item,
#extensions_menu .inline-drawer-toggle {
    background: #2a2a2a !important; /* 原 #fff → 深灰 */
    background-image: none !important;
    border: 1px solid #4a4a4a !important; /* 原 #E0E0E0 → 深灰边框 */
    color: #cccccc !important; /* 原 #555 → 亮灰 */
    box-shadow: none !important;
    text-shadow: none !important;
    border-radius: 0 !important;
    margin-bottom: 6px !important;
    transition: all 0.2s ease;
}

.inline-drawer-toggle:hover,
.list-group-item:hover {
    background: #3a3a3a !important; /* 原 #FAFAFA → 深灰悬浮 */
    color: #ffffff !important; /* 原 #000 → 白 */
}

.inline-drawer-toggle i,
.inline-drawer-toggle .fa-chevron-down,
.inline-drawer-toggle .fa-chevron-right,
.inline-drawer-icon {
    color: #aaaaaa !important; /* 原 #999 → 稍亮灰 */
    text-shadow: none !important;
}

/* ================================================= */

/* 2. 输入控件扁平化 */
.text_pole,
textarea,
select,
.menu_button,
.character_select,
.group_select,
input[type="text"],
input[type="number"] {
    background-color: #2c2c2c !important; /* 原 #fff → 深色 */
    border: 1px solid #555 !important; /* 原 #E0E0E0 → 深灰 */
    color: #e6e6e6 !important; /* 原 #444 → 浅色 */
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: all .2s ease;
}

.menu_button {
    background-color: #333 !important; /* 原 #FAFAFA → 深灰 */
}

/* 交互反馈 */
.text_pole:focus,
textarea:focus,
select:focus {
    border-color: #888 !important; /* 原 #AAA → 更亮灰 */
    background-color: #3a3a3a !important; /* 原 #fff → 深色聚焦 */
    box-shadow: none !important;
    outline: none !important;
}

.menu_button:hover {
    background-color: #4a4a4a !important; /* 原 #F0F0F0 → 深色 */
    color: #ffffff !important; /* 原 #000 → 白 */
}

/* 核心修复:解决预设编辑条目文字不可见问题 */
#completion_prompt_manager_list {
    background-color: transparent !important;
    border: none !important;
}

#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,
#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,
#completion_prompt_manager_list .text_muted,
.completion_prompt_manager_prompt_name {
    color: #dddddd !important; /* 原 #555 → 亮灰 */
    opacity: 1 !important;
    -webkit-text-fill-color: #dddddd !important;
    text-shadow: none !important;
}

/* ===== 滑块与轨道样式完全独立与隔离方案 ===== */

/* 1. 滑块轨道 (那条横线) */
input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: #aaaaaa !important; /* 原 #000000 → 浅灰轨道，深色背景下可见 */
    height: 4px !important;
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
    filter: none !important;
    mix-blend-mode: normal !important;
    opacity: 1 !important;
}

/* 滑块微调:极致紧凑且保持图标完整 */
input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: linear-gradient(#aaaaaa, #aaaaaa) center/100% 2px no-repeat !important; /* 原 #1a1a1a → 浅灰轨道 */
    height: 28px !important;
    border: 0 !important;
    outline: 0 !important;
    cursor: pointer;
    overflow: visible !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    width: 38px !important;
    height: 26px !important;
    background: url('https://files.catbox.moe/5ijx5m.png') center/contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.5)) !important; /* 阴影加深 */
}

input[type="range"]::-moz-range-thumb {
    width: 38px !important;
    height: 26px !important;
    background: url('https://files.catbox.moe/5ijx5m.png') center/contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.5)) !important;
}

/* 复选框:去除灰色背景/更换框纹图标/强化内外框差分 */
input[type="checkbox"] {
    border-radius: 0 !important;
    -webkit-appearance: none;
    appearance: none;
    background: transparent !important;
    border: 1px solid #777 !important; /* 原 #CCC → 深灰边框 */
    width: 16px;
    height: 16px;
    position: relative;
    vertical-align: middle;
    cursor: pointer;
    outline: none !important;
}

input[type="checkbox"]:checked {
    border-color: #cccccc !important; /* 原 #1a1a1a → 亮灰边框 */
    background: transparent !important;
}

input[type="checkbox"]::before {
    content: none !important;
}

input[type="checkbox"]:checked::after {
    content: '' !important;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%) !important;
    width: 14px;
    height: 14px;
    background: url('https://files.catbox.moe/w4sj3e.jpg') center/cover no-repeat !important;
}

::-webkit-scrollbar {
    display: none;
}

/* 顶栏图标缩小 */
#top-bar {
    margin: 0 auto;
    left: 0;
    right: 0;
    display: inline-block;
    height: 24px;
    position: absolute;
    box-shadow: none;
    opacity: 0;
    z-index: 3005;
}

.drawer-icon {
    transform: scale(.55);
    color: #cccccc !important; /* 原 #000 → 浅灰 */
}

/* 输入栏交互 */
#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 94% !important;
    max-width: 800px;
    margin: 10px auto !important;
    background: #1e1e1e !important; /* 原 #fff → 深色 */
    border: 1px solid #4a4a4a !important; /* 原 #DDD → 深灰 */
    border-radius: 0 !important;
    box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.2) !important; /* 阴影加深 */
}

#nonQRFormItems {
    padding: 4px 12px !important;
    position: relative;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    order: 25;
    width: 100%;
    min-height: 40px !important;
    align-items: center;
    overflow: hidden;
    background-color: #1e1e1e !important; /* 原 #fff → 深色 */
    border: none !important;
    box-shadow: none !important;
    z-index: 50;
}

.qr--buttons {
    opacity: 0;
    visibility: hidden;
    max-height: 0;
    margin: 0 !important;
    padding: 0 !important;
    transform: translateY(15px);
    transition: all .3s cubic-bezier(.2, 1, .3, 1);
    overflow: hidden;
}

#send_form:focus-within .qr--buttons {
    opacity: 1;
    visibility: visible;
    max-height: 300px;
    margin-bottom: 8px !important;
    transform: translateY(0);
    pointer-events: auto;
}

#rightSendForm>div:not(.mes_stop),
#leftSendForm>div {
    transform: scale(.6) !important;
    color: #dddddd !important; /* 原 #000 → 浅灰 */
}

/* 输入栏美化与聊天框渐变:合并精简版 */
#send_textarea {
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    color: #e0e0e0 !important; /* 原 #333 → 浅色文字 */
}

#send_textarea::placeholder,
#send_textarea::-webkit-input-placeholder {
    color: transparent !important;
    opacity: 0 !important;
    -webkit-text-fill-color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "似曾相识燕归来" !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-style: oblique !important;
    font-size: 13px !important;
    pointer-events: none !important;
    z-index: 10 !important;
    white-space: nowrap !important;
    color: #aaaaaa !important; /* 原 #999 → 浅灰 */
}

#chat {
    -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 15px, #000 calc(100% - 25px), transparent 100%);
    mask-image: linear-gradient(to bottom, transparent 0, #000 15px, #000 calc(100% - 25px), transparent 100%);
}

/* 思维链美化 - 间距优化版 */
.mes_reasoning_details {
    width: 100% !important;
    margin: 15px 0 !important;
    border: 0 !important;
    background: transparent !important;
    overflow: visible !important;
}

.mes_reasoning_header,
.mes_reasoning_summary,
.mes_reasoning_header_text {
    background: #2d2b26 !important; /* 原 #fdfcf8 → 深暖灰 */
    background-image: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

.mes_reasoning_summary {
    width: 100% !important;
    box-sizing: border-box !important;
    border: 1px solid #777 !important; /* 原 #444 → 深灰边框 */
    border-left: 4px solid #d9534f !important; /* 原 #c0392b → 稍亮红 */
    padding: 8px 15px !important;
    color: #e0e0e0 !important; /* 原 #1a1a1a → 浅色 */
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    min-height: 32px !important;
    cursor: pointer !important;
    box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.2) !important; /* 阴影调整 */
    justify-content: flex-start !important;
}

/* 燕子图标 */
.mes_reasoning_summary::before {
    content: '' !important;
    position: absolute;
    left: 8px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 16px !important;
    height: 14px !important;
    background: url('https://files.catbox.moe/5ijx5m.png') center / contain no-repeat !important;
    filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.5)) !important;
}

/* 横排文字 */
.mes_reasoning_summary::after {
    content: '杳杳春来时' !important;
    position: absolute;
    left: 30px !important; /* 根据图标宽度微调，避免重叠 */
    top: 50% !important;
    transform: translateY(-50%) !important;
    white-space: nowrap !important;
}


.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_arrow {
  font-size: 0 !important;
}
.mes_reasoning_arrow::before {
  content: ''; /* 去除箭头 */
  font-size: 11px; 
  color: rgba(255, 255, 255, 0.5);
  display: inline-block; 
  transition: transform 0.3s ease;
}
.mes_reasoning {
    width: 100% !important;
    box-sizing: border-box !important;
    background: #24221f !important; /* 原 #f9f8f4 → 深暖灰 */
    border: 1px dashed #777 !important; /* 原 #444 → 深灰 */
    border-top: 0 !important;
    color: #cccccc !important; /* 原 #444 → 浅灰 */
    font-size: .9em !important;
    line-height: 1.7 !important;
    padding: 15px !important;
    margin: 0 !important;
}

.mes_reasoning_header_icon,
.mes_reasoning_details summary::marker {
    position: absolute !important;
    right: 10px !important;
    top: 50%;
    transform: translateY(-50%) !important;
    color: #cccccc !important; /* 原 #444 → 浅灰 */
}


/* --- 2. 正文文字样式加固 --- */
/* 加粗：浅灰荧光笔效果 */
.mes_text strong {
    position: relative !important;
    z-index: 1 !important;
    color: #f0f0f0 !important; /* 原 #333 → 亮白 */
    font-weight: bold !important;
    background: linear-gradient(to bottom, transparent 60%, rgba(160, 160, 160, 0.4) 40%) !important; /* 灰度调整 */
}

/* 斜体美化:燕子修饰+立体投影 */
.mes_text em {
    position: relative !important;
    padding-left: 15px !important;
    font-style: italic !important;
    color: #bbbbbb !important; /* 原 #666 → 浅灰 */
    display: inline-block !important;
}

.mes_text em::before {
    content: '' !important;
    position: absolute !important;
    left: 0;
    top: 50%;
    transform: translateY(-50%) !important;
    width: 18px;
    height: 12px;
    background: url('https://files.catbox.moe/5ijx5m.png') center/contain no-repeat !important;
    filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.6)) !important;
}

/* 多行代码:燕子图标标签+白色立体投影 */
pre {
    background: #2d2b26 !important; /* 原 #fdfcf8 → 深暖灰 */
    color: #e0e0e0 !important; /* 原 #333 → 浅色 */
    border: 1px solid #777 !important; /* 原 #444 → 深灰 */
    box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.2) !important;
    margin: 20px 0 !important;
    padding: 28px 12px 12px !important;
    position: relative !important;
}

pre code,
pre span {
    background: transparent !important;
    color: inherit !important;
    text-shadow: none !important;
}

pre::before {
    content: '似曾相识燕归来。' !important;
    position: absolute;
    top: 0;
    left: 0;
    font-size: 9px !important;
    font-weight: 700 !important;
    color: #eeeeee !important; /* 原 #fff → 亮白 */
    background: #2c2c2c !important; /* 原 #444 → 深灰 */
    padding: 2px 10px 2px 28px !important;
    letter-spacing: 1px;
}

pre::after {
    content: '' !important;
    position: absolute;
    top: 3px;
    left: 8px;
    width: 16px;
    height: 12px;
    background: url('https://files.catbox.moe/5ijx5m.png') center/contain no-repeat !important;
    filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.6)) !important;
    z-index: 10;
}

/* 引号与单行代码:极简红字/墨拓封签 */
q {
    color: #e06c75 !important; /* 原 #c0392b → 柔和红 */
    background: transparent !important;
    border: 0 !important;
    padding: 0 !important;
    font-style: normal !important;
}

:not(pre)>code {
    background: #1a1a1a !important; /* 保持深色 */
    color: #f0f0f0 !important; /* 原 #fdfcf8 → 亮白 */
    padding: 2px 6px !important;
    border-right: 4px solid #d9534f !important; /* 原 #c0392b → 稍亮红 */
    font-weight: 700 !important;
    margin: 0 2px !important;
}

blockquote {
    margin: 18px 0 !important;
    padding: 12px 15px !important;
    border-left: 4px solid #777 !important; /* 原 #444 → 深灰 */
    background: #24221f !important; /* 原 #f9f8f4 → 深暖灰 */
    color: #cccccc !important; /* 原 #555 → 浅灰 */
    font-style: normal !important;
    position: relative !important;
    display: block !important;
}

blockquote::after {
    content: '拾遗' !important;
    position: absolute;
    top: -8px;
    right: 10px;
    background: #2c2c2c !important; /* 原 #444 → 深灰 */
    color: #eeeeee !important; /* 原 #fff → 亮白 */
    font-size: 9px;
    padding: 1px 6px;
    font-weight: 700 !important;
}

/* ============================================================
   ★ 封面设计 (Magazine Cover Style) - 2025 Edition
   ============================================================ */

/* 1. 消息主体：模拟画报纸张 */
body.bubblechat .mes,
.mes {
    padding: 20px !important;
    padding-top: 260px !important;
    border-radius: 0 !important;
    border: 1px solid #3a3a3a !important; /* 原 #333 → 深灰 */
    box-shadow: 10px 10px 0px rgba(0, 0, 0, 0.15) !important; /* 阴影加深 */
    max-width: 380px !important;
    margin: 40px auto 20px auto !important;
    position: relative;
    background: #1e1e1e !important; /* 原 #fff → 深色 */
    overflow: visible !important;
}

/* 2. 封面容器：不对称比例布局 */
.mesAvatarWrapper {
    width: calc(100% - 20px) !important;
    height: 220px !important;
    position: absolute !important;
    left: 10px !important;
    top: 10px !important;
    z-index: 5 !important;
    background: #2a2a2a !important; /* 原 #f8f8f8 → 深灰 */
    overflow: hidden !important;
    border: 1px solid #3a3a3a !important; /* 原 #eee → 深灰 */
}

/* 3. 头像处理：作为杂志主图，偏右放置 */
.mesAvatarWrapper .avatar {
    width: 65% !important;
    height: 100% !important;
    position: absolute !important;
    right: 0 !important;
    top: 0 !important;
}

.mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    filter: contrast(1.05) sepia(0.1); /* 保持原滤镜 */
}

/* 4. 封面装饰 A：纵向艺术字/刊名 */
.mesAvatarWrapper::before {
    content: "VO.2025 ARCHIVE / DESIGNED BY MOCHA" !important;
    position: absolute !important;
    left: 5px !important;
    top: 50% !important;
    transform: rotate(-90deg) translateY(-50%) !important;
    transform-origin: left center !important;
    font-size: 8px !important;
    color: #aaaaaa !important; /* 原 #999 → 浅灰 */
    letter-spacing: 2px !important;
    white-space: nowrap !important;
    z-index: 10;
}

/* 5. 封面装饰 封面印章做旧:边缘侵蚀与朱砂洇染效果 */
.mesAvatarWrapper::after {
    content: "目" !important;
    position: absolute !important;
    left: 15px !important;
    bottom: 15px !important;
    width: 20px !important;
    height: 20px !important;
    color: #d65c5c !important; /* 原 #b23a3a → 稍亮红 */
    font-size: 11px !important;
    line-height: 18px !important;
    text-align: center !important;
    font-weight: 900 !important;
    z-index: 10 !important;
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="r"><feTurbulence type="fractalNoise" baseFrequency="0.15" numOctaves="3"/><feDisplacementMap in="SourceGraphic" scale="8"/></filter><rect x="5" y="5" width="90" height="90" fill="none" stroke="%23d65c5c" stroke-width="10" filter="url(%23r)"/></svg>') !important; /* 印章红色调同步 */
    background-size: contain !important;
    background-repeat: no-repeat !important;
    filter: contrast(1.2) opacity(0.85) drop-shadow(0 0 0.5px #d65c5c) !important;
}

/* 6. 角色名字：主标题化 (Typography) */
.mes .name_text {
    font-size: 1.6em !important;
    font-weight: 900 !important;
    position: absolute !important;
    left: 45px !important;
    top: 110px !important;
    text-align: left !important;
    color: #f0f0f0 !important; /* 原 #000 → 亮白 */
    text-transform: uppercase;
    letter-spacing: -1px !important;
    z-index: 20;
    text-shadow: 2px 2px 0 #1e1e1e, -2px -2px 0 #1e1e1e, 2px -2px 0 #1e1e1e, -2px 2px 0 #1e1e1e !important; /* 深色镂空阴影 */
}

/* 7. 副标题/简介：艺术性微调 */
.mes .name_text::after {
    content: "EXPERIMENTAL COVER DESIGN / NO.04" !important;
    display: block !important;
    font-size: 9px !important;
    font-weight: normal !important;
    letter-spacing: 3px !important;
    margin-top: 5px !important;
    color: #aaaaaa !important; /* 原 #666 → 浅灰 */
}

/* 8. 移除冗余的计时器/ID背景色，使其完全融入杂志面 */
.mes .mes_timer,
.mes .mesIDDisplay,
.mes .tokenCounterDisplay {
    background: transparent !important;
    color: #888888 !important; /* 原 #999 → 深灰 */
    top: 195px !important;
}

.mes .timestamp {
